#!/bin/zsh
# Shared worktree-materialization helpers for worktree-ticket.sh (mwt) and
# worktree-generic.sh (wt) so the two never drift. Sourced, not executed.

# .husky/_/husky.sh is gitignored and generated by the `prepare` script on yarn
# install. A fresh worktree never runs yarn, so the tracked hooks (which source
# that file) break every commit until husky is installed here.
#   $1 worktree dir
function wt_install_hooks() {
    local DIR="$1"
    [[ -d "$DIR/.husky" && ! -f "$DIR/.husky/_/husky.sh" ]] || return 0
    echo "Installing git hooks (husky)…"
    if [[ -x "$DIR/node_modules/.bin/husky" ]]; then
        (cd "$DIR" && ./node_modules/.bin/husky install)
    else
        (cd "$DIR" && npx husky install)
    fi
}

# APFS copy-on-write clone of node_modules: ~0 disk, isolated per worktree so a
# yarn install in one ticket never mutates another's deps.
#
# `cp -c -R` clones the data blocks for free but still walks the tree in
# userspace, one copyfile(2) + inode per entry — ~4 min for a large monorepo's
# 214k files. clonefile(2) on the *directory* clones the whole hierarchy in a
# single kernel call instead: same result in ~5s. Destination must not already
# exist, which holds right after `git worktree add` since node_modules is
# untracked.
#   $1 source repo dir  $2 destination worktree dir
function wt_clone_node_modules() {
    local SRC="$1" DEST="$2"
    [[ -d "$SRC/node_modules" ]] || return 0
    echo "Cloning node_modules (APFS copy-on-write)…"
    if ! /usr/bin/python3 -c '
import ctypes, sys
libc = ctypes.CDLL("/usr/lib/libSystem.dylib", use_errno=True)
libc.clonefile.argtypes = [ctypes.c_char_p, ctypes.c_char_p, ctypes.c_int]
sys.exit(0 if libc.clonefile(sys.argv[1].encode(), sys.argv[2].encode(), 0) == 0 else 1)
' "$SRC/node_modules" "$DEST/node_modules" 2>/dev/null; then
        echo "clonefile unavailable, falling back to cp -c -R (slower)…"
        rm -rf "$DEST/node_modules"
        cp -c -R "$SRC/node_modules" "$DEST/node_modules"
    fi
}

# Basename of a repo path, used to namespace the worktree root per-repo.
#   $1 repo path
function wt_repo_name() {
    print -r -- "${1:t}"
}

# Default branch for a remote, e.g. for basing a new branch when none is
# specified. Tries the remote's HEAD symref first, then falls back to common
# default branch names.
#   $1 remote name (default: origin)
function wt_default_base_branch() {
    local REMOTE="${1:-origin}"
    local REF
    REF=$(git symbolic-ref -q "refs/remotes/$REMOTE/HEAD" 2>/dev/null) && {
        print -r -- "${REF#refs/remotes/$REMOTE/}"
        return 0
    }
    local CANDIDATE
    for CANDIDATE in main master; do
        git show-ref --verify --quiet "refs/remotes/$REMOTE/$CANDIDATE" && {
            print -r -- "$CANDIDATE"
            return 0
        }
    done
    return 1
}
